const item = $input.item.json;
const days = item.days_remaining;

let priority = 'LOW';
let action = 'Gửi email khảo sát và thư ngỏ gia hạn định kỳ.';

if (days <= 7) {
  priority = 'URGENT';
  action = 'CẢNH BÁO KHẨN: Gọi điện trực tiếp cho Quản lý tài khoản và gửi báo giá gia hạn ưu đãi.';
} else if (days <= 15) {
  priority = 'HIGH';
  action = 'Liên hệ phụ trách đối tác, sắp xếp cuộc họp review hiệu quả dịch vụ.';
} else if (days <= 30) {
  priority = 'MEDIUM';
  action = 'Gửi thông báo nhắc nhở hợp đồng còn 30 ngày và tài liệu cập nhật bảng giá.';
}

return {
  customer_id: item.id,
  company_name: item.company_name,
  contract_id: item.contract_id,
  contract_end_date: item.contract_end_date,
  days_remaining: days,
  priority: priority,
  recommended_action: action,
  task_title: `[Gia hạn hợp đồng] ${item.company_name} - Còn ${days} ngày`
};
